import{_ as g,C as c,c as h,o as t,j as i,G as l,a8 as o,b as r,a,w as n,a9 as d}from"./chunks/framework.8HQ-OgOa.js";const k=JSON.parse('{"title":"Plugin Packaging and Distribution","description":"Plugin Packaging and Distribution","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"Plugin Packaging and Distribution","description":"Plugin Packaging and Distribution"},"headers":[],"relativePath":"en/dev/dev-guide/plugin-dev/packaging.md","filePath":"en/dev/dev-guide/plugin-dev/packaging.md"}'),p={name:"en/dev/dev-guide/plugin-dev/packaging.md"};function m(P,e,f,b,v,A){const u=c("ArticleMetadata"),s=c("Mermaid");return t(),h("div",null,[e[4]||(e[4]=i("h1",{id:"plugin-packaging-and-distribution",tabindex:"-1"},[a("Plugin Packaging and Distribution "),i("a",{class:"header-anchor",href:"#plugin-packaging-and-distribution","aria-label":'Permalink to "Plugin Packaging and Distribution"'},"​")],-1)),l(u),e[5]||(e[5]=o('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This document is intended for developers who wish to develop, package, and distribute plugins in the InkCanvasForClass ecosystem. It systematically explains the plugin package structure, version management, dependency management, packaging and installation, distribution channels, signature and verification, as well as complete workflow examples from development completion to release, and maintenance strategies. The content is refined and expanded based on the plugin SDK, host projects, and related documents in the repository to help even non-professional packagers smoothly complete plugin delivery.</p><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><ul><li>The plugin SDK is located in <code>InkCanvas.PluginSdk</code>, defining plugin interfaces, base classes, host contracts, and plugin metadata models. It is the specification all plugins must follow.</li><li>The main program <code>InkCanvasForClass.csproj</code> is the host application, responsible for scanning, loading, and managing plugins, and providing UI displays and interactions.</li><li>The plugin page <code>PluginPage.xaml.cs</code> displays the list of loaded plugins, reflecting plugin lifecycles and states.</li><li>The document <code>.qoder/.../Plugin API.md</code> defines the responsibilities and behaviors of <code>PluginManager</code> on the host side, serving as a key to understanding the plugin loading mechanism.</li></ul>',4)),(t(),r(d,null,{default:n(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22Plugin%20SDK%22%0AIPlugin%5B%22IPlugin%20Interface%22%5D%0APluginBase%5B%22PluginBase%20Abstract%20Class%22%5D%0AIPluginHost%5B%22IPluginHost%20Host%20Contract%22%5D%0APluginInfo%5B%22PluginInfo%20Metadata%20Model%22%5D%0ASdkProj%5B%22InkCanvas.PluginSdk.csproj%22%5D%0Aend%0Asubgraph%20%22Host%20Application%22%0AHostProj%5B%22InkCanvasForClass.csproj%22%5D%0APluginPage%5B%22PluginPage.xaml.cs%22%5D%0Aend%0AIPlugin%20--%3E%20PluginBase%0APluginBase%20--%3E%20IPluginHost%0APluginInfo%20--%3E%20PluginPage%0ASdkProj%20--%3E%20HostProj%0AHostProj%20--%3E%20PluginPage%0A"})]),fallback:n(()=>e[0]||(e[0]=[a(" Loading... ",-1)])),_:1})),e[6]||(e[6]=o('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li>Plugin Interface <code>IPlugin</code>: Defines plugin identification, name, version, description, author, loading order, and conventions for initialization, shutdown, main views, and settings views.</li><li>Plugin Base Class <code>PluginBase</code>: Provides general lifecycle hooks, logging and error recording, and service retrieval capabilities, injected through the host to achieve loose coupling.</li><li>Host Contract <code>IPluginHost</code>: Provides logging, error logging, and service registration/retrieval capabilities, serving as the bridge for plugin-host communication.</li><li>Plugin Metadata <code>PluginInfo</code>: Carries plugin ID, name, version, description, author, loading order, instance, and load status, used for UI display and management.</li><li>Host Project <code>InkCanvasForClass.csproj</code>: Defines target frameworks, runtime identifiers, packaging and deployment properties, as well as resource embedding and third-party dependencies.</li><li>Plugin Page <code>PluginPage.xaml.cs</code>: Displays the count and list of loaded plugins, reflecting plugin loading and exception handling processes.</li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>The plugin architecture adopts the design of &quot;Interface + Abstract Base Class + Host Contract.&quot; By implementing <code>IPlugin</code> and inheriting <code>PluginBase</code>, plugins acquire uniform lifecycle and service access capabilities. The host scans the <code>Plugins</code> directory via <code>PluginManager</code> (see document), dynamically loads assemblies, filters <code>IPlugin</code> implementations via reflection, sorts them by <code>Order</code>, and triggers events, supporting single and batch unloading.</p>',4)),(t(),r(d,null,{default:n(()=>[l(s,{id:"mermaid-76",class:"mermaid",graph:"classDiagram%0Aclass%20IPlugin%20%7B%0A%2Bstring%20Id%0A%2Bstring%20Name%0A%2Bstring%20Version%0A%2Bstring%20Description%0A%2Bstring%20Author%0A%2Bint%20Order%0A%2BInitialize(host)%0A%2BShutdown()%0A%2BGetMainView()%0A%2BGetSettingsView()%0A%7D%0Aclass%20PluginBase%20%7B%0A-IPluginHost%20Host%0A%2BInitialize(host)%0A%2BShutdown()%0A%2BGetMainView()%0A%2BGetSettingsView()%0A%2BLog(message)%0A%2BLogError(message%2C%20ex)%0A%2BGetService~T~()%0A%7D%0Aclass%20IPluginHost%20%7B%0A%2BLog(message)%0A%2BLogError(message%2C%20ex)%0A%2BGetService~T~()%0A%2BRegisterService~T~(service)%0A%7D%0Aclass%20PluginInfo%20%7B%0A%2Bstring%20Id%0A%2Bstring%20Name%0A%2Bstring%20Version%0A%2Bstring%20Description%0A%2Bstring%20Author%0A%2Bint%20Order%0A%2BIPlugin%20Instance%0A%2Bbool%20IsLoaded%0A%7D%0AIPlugin%20%3C%7C..%20PluginBase%0APluginBase%20--%3E%20IPluginHost%20%3A%20%22Depends%20on%22%0APluginInfo%20--%3E%20IPlugin%20%3A%20%22Holds%20instance%22%0A"})]),fallback:n(()=>e[1]||(e[1]=[a(" Loading... ",-1)])),_:1})),e[7]||(e[7]=o('<h2 id="detailed-component-analysis" tabindex="-1">Detailed Component Analysis <a class="header-anchor" href="#detailed-component-analysis" aria-label="Permalink to &quot;Detailed Component Analysis&quot;">​</a></h2><h3 id="plugin-interface-and-base-class" tabindex="-1">Plugin Interface and Base Class <a class="header-anchor" href="#plugin-interface-and-base-class" aria-label="Permalink to &quot;Plugin Interface and Base Class&quot;">​</a></h3><ul><li><code>IPlugin</code> specifies the basic metadata and lifecycle methods of plugins, ensuring that the host can manage different plugins uniformly.</li><li><code>PluginBase</code> provides default implementations and host interaction capabilities, reducing duplicate code and facilitating extension.</li><li><code>IPluginHost</code> provides logging, error recording, and service registration/retrieval for plugins, forming a stable extension point.</li></ul>',3)),(t(),r(d,null,{default:n(()=>[l(s,{id:"mermaid-100",class:"mermaid",graph:"sequenceDiagram%0Aparticipant%20Host%20as%20%22Host%22%0Aparticipant%20Manager%20as%20%22PluginManager%22%0Aparticipant%20Asm%20as%20%22Plugin%20Assembly%22%0Aparticipant%20Plugin%20as%20%22IPlugin%20Instance%22%0AHost-%3E%3EManager%20%3A%20%22Scan%20Plugins%20directory%22%0AManager-%3E%3EAsm%20%3A%20%22Dynamically%20load%20assembly%22%0AManager-%3E%3EAsm%20%3A%20%22Filter%20IPlugin%20implementations%20via%20reflection%22%0AManager-%3E%3EPlugin%20%3A%20%22Construct%20instance%20and%20Initialize(this)%22%0APlugin--%3E%3EManager%20%3A%20%22Return%20main%20view%2Fsettings%20view%22%0AManager--%3E%3EHost%20%3A%20%22Trigger%20PluginLoaded%20event%22%0A"})]),fallback:n(()=>e[2]||(e[2]=[a(" Loading... ",-1)])),_:1})),e[8]||(e[8]=i("h2",{id:"dependency-analysis",tabindex:"-1"},[a("Dependency Analysis "),i("a",{class:"header-anchor",href:"#dependency-analysis","aria-label":'Permalink to "Dependency Analysis"'},"​")],-1)),e[9]||(e[9]=i("ul",null,[i("li",null,"Dependencies between the Plugin SDK and host projects: Host projects reference the Plugin SDK to ensure compile-time type safety and runtime loading consistency."),i("li",null,"Third-Party Dependencies: The host project imports multiple NuGet packages covering UI, interop, notifications, logging, etc. Plugins should avoid high-version dependencies that conflict with the host."),i("li",null,"Resources & Embedding: Binary resources like IACore participate in host building via embedding, and plugins should not generate naming conflicts with them.")],-1)),(t(),r(d,null,{default:n(()=>[l(s,{id:"mermaid-121",class:"mermaid",graph:"graph%20LR%0ASdk%5B%22InkCanvas.PluginSdk.csproj%22%5D%20--%3E%20Host%5B%22InkCanvasForClass.csproj%22%5D%0AThirdParty%5B%22Third-Party%20NuGet%20Packages%22%5D%20--%3E%20Host%0AEmbedded%5B%22Embedded%20Resources%20(IACore)%22%5D%20--%3E%20Host%0A"})]),fallback:n(()=>e[3]||(e[3]=[a(" Loading... ",-1)])),_:1})),e[10]||(e[10]=o('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>Dynamic Loading &amp; Unloading: Plugins are loaded using a collectible <code>AssemblyLoadContext</code> to avoid memory leaks and resource occupancy. It is recommended that plugins release unmanaged resources in <code>Shutdown</code>.</li><li>UI Rendering: The plugin page renders plugin cards on demand, and exception capturing and empty list prompts reduce UI response times.</li><li>Dependency Minimization: Plugins should reuse services provided by the host as much as possible, reducing extra dependencies to avoid version conflicts with host dependencies.</li></ul><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><ul><li>Plugin Not Displayed: Check whether the host has scanned the <code>Plugins</code> directory correctly, whether the plugin implements <code>IPlugin</code>, and whether it is injected into the host via <code>Initialize</code>.</li><li>Plugin Load Failure: Review host logs and error records to confirm dependency versions, resource paths, and permissions.</li><li>UI Anomalies: Verify the consistency of the plugin main view/settings view return values with UI thread calls in the host.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Through standardized plugin interfaces, uniform base classes, and host contracts, combined with the host project&#39;s resource and dependency management, developers can quickly build plugins that comply with ecological specifications. Adhering to the packaging and distribution processes in this document ensures that plugins run stably on different platforms and are delivered smoothly.</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><h3 id="plugin-package-structure-and-composition" tabindex="-1">Plugin Package Structure and Composition <a class="header-anchor" href="#plugin-package-structure-and-composition" aria-label="Permalink to &quot;Plugin Package Structure and Composition&quot;">​</a></h3><ul><li>Required Files <ul><li>Plugin Assembly: Contains classes implementing <code>IPlugin</code> and resources.</li><li>Plugin Metadata: Information like version, name, author, and description read by the host (usually from the plugin&#39;s own properties or manifest).</li></ul></li><li>Optional Resources <ul><li>Icons, localized resources, fonts, styles, etc.</li></ul></li><li>Metadata Files <ul><li>Plugin Manifest (recommended): Contains ID, version, dependencies, compatibility statements, etc., facilitating recognition by host and distribution systems.</li></ul></li></ul><h3 id="version-management-strategy" tabindex="-1">Version Management Strategy <a class="header-anchor" href="#version-management-strategy" aria-label="Permalink to &quot;Version Management Strategy&quot;">​</a></h3><ul><li>Version Numbering Rules <ul><li>Semantic versioning (Major.Minor.Patch) is recommended, e.g., 1.2.3.</li><li>Plugin versions are decoupled from host versions, but must declare the minimum host version requirement.</li></ul></li><li>Semantic Versioning <ul><li>Major Version Change: Breaking updates, requiring manual upgrades by users.</li><li>Minor Version Change: New features, maintaining backward compatibility.</li><li>Patch Version: Issue fixes, maintaining complete compatibility.</li></ul></li><li>Version Compatibility Statement <ul><li>Declare the supported range of host versions in the plugin manifest to avoid loading on incompatible versions.</li></ul></li></ul><h3 id="dependency-management-mechanism" tabindex="-1">Dependency Management Mechanism <a class="header-anchor" href="#dependency-management-mechanism" aria-label="Permalink to &quot;Dependency Management Mechanism&quot;">​</a></h3><ul><li>Runtime Dependency Check <ul><li>Plugins should avoid directly depending on third-party library versions that conflict with the host.</li><li>Share capabilities between plugins by registering services via the host <code>IPluginHost.RegisterService</code>.</li></ul></li><li>Third-Party Library Referencing <ul><li>Prioritize using capabilities already provided by the host to reduce redundant dependencies.</li><li>If referencing is necessary, ensure that versions are locked consistently with the host to avoid runtime conflicts.</li></ul></li><li>Conflict Resolution <ul><li>When dependency conflicts occur, prioritize upgrading or downgrading plugin dependencies to versions consistent with the host.</li><li>Locate conflict sources using logs and error records provided by the host.</li></ul></li></ul><h3 id="packaging-tools-and-automation-process" tabindex="-1">Packaging Tools and Automation Process <a class="header-anchor" href="#packaging-tools-and-automation-process" aria-label="Permalink to &quot;Packaging Tools and Automation Process&quot;">​</a></h3><ul><li>Command Line Tools <ul><li>Use the dotnet CLI to build and package, generating plugin assemblies and resources.</li></ul></li><li>Build Scripts <ul><li>Define build matrices (x86/x64/arm64) in CI/CD to execute restore/build/publish.</li></ul></li><li>Automation Process <ul><li>Automatically compress to a zip package after building, containing plugin assemblies and necessary resources.</li><li>Generate checksums (such as SHA256) and version metadata files, facilitating distribution and verification.</li></ul></li></ul><h3 id="installer-creation" tabindex="-1">Installer Creation <a class="header-anchor" href="#installer-creation" aria-label="Permalink to &quot;Installer Creation&quot;">​</a></h3><ul><li>Installation Package Generation <ul><li>Package the plugin zip package and installation scripts into MSI/EXE installers.</li></ul></li><li>Registry Configuration <ul><li>Write plugin installation paths and version information during installation, facilitating identification by the host.</li></ul></li><li>Uninstaller Creation <ul><li>Provide uninstall logic to clean up registry entries and files, restoring the initial state.</li></ul></li></ul><h3 id="distribution-channel-selection" tabindex="-1">Distribution Channel Selection <a class="header-anchor" href="#distribution-channel-selection" aria-label="Permalink to &quot;Distribution Channel Selection&quot;">​</a></h3><ul><li>Official Plugin Market <ul><li>Publish on the official community platform, providing version history and download statistics.</li></ul></li><li>Third-Party Platforms <ul><li>GitHub Releases, NuGet (if applicable), technical community resource sites.</li></ul></li><li>Self-built Distribution System <ul><li>Set up internal or public download and update channels, cooperating with signature verification and version pushes.</li></ul></li></ul><h3 id="signature-and-verification-mechanism" tabindex="-1">Signature and Verification Mechanism <a class="header-anchor" href="#signature-and-verification-mechanism" aria-label="Permalink to &quot;Signature and Verification Mechanism&quot;">​</a></h3><ul><li>Digital Signature <ul><li>Digitally sign plugin packages and installers to improve trustworthiness.</li></ul></li><li>Integrity Check <ul><li>Generate and verify SHA256 checksums to prevent tampering.</li></ul></li><li>Source Verification <ul><li>Verify signatures and sources in the host, only allowing plugins from trusted channels to load.</li></ul></li></ul><h3 id="complete-packaging-example-from-development-to-release" tabindex="-1">Complete Packaging Example (From Development to Release) <a class="header-anchor" href="#complete-packaging-example-from-development-to-release" aria-label="Permalink to &quot;Complete Packaging Example (From Development to Release)&quot;">​</a></h3><ul><li>Development Phase <ul><li>Implement <code>IPlugin</code> and inherit <code>PluginBase</code>, perfecting main views and settings views.</li></ul></li><li>Build Phase <ul><li>Use <code>dotnet build</code> to generate plugin assemblies, copying them to the host <code>Plugins</code> directory for joint debugging.</li></ul></li><li>Packaging Phase <ul><li>Package plugin assemblies and resources into a zip file, generating version metadata and checksums.</li></ul></li><li>Release Phase <ul><li>Upload to the official plugin market or self-built distribution system, attaching changelogs and installation instructions.</li></ul></li><li>User Installation <ul><li>Download the installation package, execute the installation, and the host automatically scans and loads the plugin.</li></ul></li></ul><h3 id="post-release-maintenance-strategy" tabindex="-1">Post-Release Maintenance Strategy <a class="header-anchor" href="#post-release-maintenance-strategy" aria-label="Permalink to &quot;Post-Release Maintenance Strategy&quot;">​</a></h3><ul><li>Update Push <ul><li>Publish new versions through official channels, providing upgrade prompts and auto-updates (if feasible).</li></ul></li><li>User Feedback Handling <ul><li>Establish feedback collection and classification mechanisms, locating issues in combination with host logs.</li></ul></li><li>Issue Fixing Process <ul><li>Fast fix and release of hotfix patches, ensuring compatibility with host versions.</li></ul></li></ul>',25))])}const I=g(p,[["render",m]]);export{k as __pageData,I as default};
